const testCases = [
  {
    order: 1,
    id: "TC_WC_001",
    name: "No crea pending_task duplicado",
    priority: "CRITICAL",
    category: "DUPLICATE_PREVENTION",
    description: "Si ya existe un pending_task para el mismo user_id + related_id, NO debe crear otro",
    setup: [
      "UPDATE user_weekly_schedule SET \"Completed\" = false, planned_day = (NOW() AT TIME ZONE 'America/Bogota')::date::text WHERE user_id = 'e2e00003-0000-0000-0000-000000000003' AND week = 1",
      "DELETE FROM pending_tasks WHERE user_id = 'e2e00003-0000-0000-0000-000000000003'",
      "INSERT INTO pending_tasks (user_id, task_type, related_id, session_name, week, status) SELECT 'e2e00003-0000-0000-0000-000000000003', 'CONFIRMAR_RUTINA', day_routine_id, session_name, 1, 'pending' FROM user_weekly_schedule WHERE user_id = 'e2e00003-0000-0000-0000-000000000003' AND week = 1 FETCH FIRST 1 ROW ONLY"
    ],
    cleanup: [
      "DELETE FROM pending_tasks WHERE user_id = 'e2e00003-0000-0000-0000-000000000003'"
    ],
    verification: {
      description: "Debe haber exactamente 1 pending_task (no duplicado)",
      query: "SELECT COUNT(*) as cnt FROM pending_tasks WHERE user_id = 'e2e00003-0000-0000-0000-000000000003' AND task_type = 'CONFIRMAR_RUTINA'",
      expected: 1,
      operator: "equals"
    }
  },
  {
    order: 2,
    id: "TC_WC_002",
    name: "Crea pending_task cuando no existe",
    priority: "CRITICAL",
    category: "TASK_CREATION",
    description: "Si NO existe pending_task previo, debe crear uno nuevo",
    setup: [
      "DELETE FROM pending_tasks WHERE user_id = 'e2e00003-0000-0000-0000-000000000003'",
      "UPDATE user_weekly_schedule SET \"Completed\" = false, planned_day = (NOW() AT TIME ZONE 'America/Bogota')::date::text WHERE user_id = 'e2e00003-0000-0000-0000-000000000003' AND week = 1"
    ],
    cleanup: [
      "DELETE FROM pending_tasks WHERE user_id = 'e2e00003-0000-0000-0000-000000000003'"
    ],
    verification: {
      description: "Debe existir exactamente 1 pending_task nuevo",
      query: "SELECT COUNT(*) as cnt FROM pending_tasks WHERE user_id = 'e2e00003-0000-0000-0000-000000000003' AND task_type = 'CONFIRMAR_RUTINA'",
      expected: 1,
      operator: "equals"
    }
  },
  {
    order: 3,
    id: "TC_WC_003",
    name: "No procesa usuarios sin workout hoy",
    priority: "HIGH",
    category: "FILTER",
    description: "Si el usuario no tiene workout programado para hoy, no debe crear pending_task",
    setup: [
      "UPDATE user_weekly_schedule SET planned_day = ((NOW() AT TIME ZONE 'America/Bogota')::date + INTERVAL '1 day')::date::text WHERE user_id = 'e2e00003-0000-0000-0000-000000000003' AND week = 1",
      "DELETE FROM pending_tasks WHERE user_id = 'e2e00003-0000-0000-0000-000000000003'"
    ],
    cleanup: [
      "UPDATE user_weekly_schedule SET planned_day = (NOW() AT TIME ZONE 'America/Bogota')::date::text WHERE user_id = 'e2e00003-0000-0000-0000-000000000003' AND week = 1"
    ],
    verification: {
      description: "No debe existir pending_task",
      query: "SELECT COUNT(*) as cnt FROM pending_tasks WHERE user_id = 'e2e00003-0000-0000-0000-000000000003'",
      expected: 0,
      operator: "equals"
    }
  },
  {
    order: 4,
    id: "TC_WC_004",
    name: "No procesa workouts ya completados",
    priority: "HIGH",
    category: "FILTER",
    description: "Si el workout ya está marcado como Completed=true, no debe crear pending_task",
    setup: [
      "UPDATE user_weekly_schedule SET \"Completed\" = true, planned_day = (NOW() AT TIME ZONE 'America/Bogota')::date::text WHERE user_id = 'e2e00003-0000-0000-0000-000000000003' AND week = 1",
      "DELETE FROM pending_tasks WHERE user_id = 'e2e00003-0000-0000-0000-000000000003'"
    ],
    cleanup: [
      "UPDATE user_weekly_schedule SET \"Completed\" = false WHERE user_id = 'e2e00003-0000-0000-0000-000000000003' AND week = 1"
    ],
    verification: {
      description: "No debe existir pending_task para workout completado",
      query: "SELECT COUNT(*) as cnt FROM pending_tasks WHERE user_id = 'e2e00003-0000-0000-0000-000000000003'",
      expected: 0,
      operator: "equals"
    }
  }
];

const sortedTests = testCases.sort((a, b) => a.order - b.order);
$execution.customData.set('startTime', new Date().toISOString());
$execution.customData.set('totalTests', sortedTests.length);
$execution.customData.set('testResults', '[]');
console.log('Tests cargados: ' + sortedTests.map(t => t.id).join(' -> '));
return sortedTests.map(tc => ({ json: tc }));

const testCase = $input.first().json;
console.log('\n========================================');
console.log('[' + testCase.order + '/' + $execution.customData.get('totalTests') + '] ' + testCase.id);
console.log('   ' + testCase.name);
console.log('   Categoria: ' + testCase.category);
console.log('========================================');
return [{ json: testCase }];

const testCase = $('Pre-Test Log').first().json;
const dbResult = $input.first().json;
let actualValue = 0;
if (dbResult) {
  actualValue = dbResult.cnt || dbResult.count || Object.values(dbResult)[0] || 0;
}
const expected = testCase.verification.expected;
const operator = testCase.verification.operator || 'equals';
let passed = false;
switch(operator) {
  case 'equals': passed = Number(actualValue) === expected; break;
  case 'gte': passed = Number(actualValue) >= expected; break;
  case 'lte': passed = Number(actualValue) <= expected; break;
  default: passed = Number(actualValue) === expected;
}
const result = {
  order: testCase.order,
  testId: testCase.id,
  testName: testCase.name,
  category: testCase.category,
  priority: testCase.priority,
  passed: passed,
  output: 'Expected: ' + expected + ', Got: ' + actualValue + ' (' + operator + ')',
  expectedRule: testCase.verification.description,
  ruleDescription: testCase.description,
  error: passed ? null : 'Verification failed: expected ' + expected + ' ' + operator + ', got ' + actualValue,
  executedAt: new Date().toISOString()
};
let allResults = [];
try {
  const existing = $execution.customData.get('testResults');
  if (existing) allResults = JSON.parse(existing);
} catch(e) {}
allResults.push(result);
$execution.customData.set('testResults', JSON.stringify(allResults));
console.log((passed ? 'PASSED' : 'FAILED') + ': ' + testCase.id + ' - ' + testCase.name);
console.log('   ' + testCase.verification.description);
console.log('   Expected: ' + expected + ', Got: ' + actualValue);
return [{ json: result }];

// Leer resultados directamente del nodo Evaluate Result
let results = [];
let source = 'None';
try {
  const evaluateResultItems = $('Evaluate Result').all();
  if (evaluateResultItems && evaluateResultItems.length > 0) {
    results = evaluateResultItems.map(item => item.json);
    source = '$(\'Evaluate Result\').all()';
  }
} catch(e) {
  console.log('Error reading from Evaluate Result: ' + e.message);
}
console.log('DATA SOURCE: ' + source);
console.log('RECORDS FOUND: ' + results.length);
const total = results.length;
const passed = results.filter(r => r.passed);
const failed = results.filter(r => !r.passed);
const passRateRaw = total > 0 ? (passed.length / total) * 100 : 0;
const passRate = passRateRaw % 1 === 0 ? passRateRaw.toFixed(0) : passRateRaw.toFixed(1);
const byCategory = results.reduce((acc, curr) => {
  const cat = curr.category || 'UNCATEGORIZED';
  if (!acc[cat]) acc[cat] = { total: 0, passed: 0, failed: 0 };
  acc[cat].total++;
  curr.passed ? acc[cat].passed++ : acc[cat].failed++;
  return acc;
}, {});
let statusEmoji = failed.length === 0 ? 'PASS' : 'FAIL';
if (total === 0) statusEmoji = 'WARN';
let mdReport = 'Test Report - GymBotWorkoutCompletion\n';
mdReport += '──────────────────────\n';
mdReport += 'Status: ' + statusEmoji + '\n';
mdReport += 'Score: ' + passRate + '% (' + passed.length + '/' + total + ')\n';
mdReport += 'Time: ' + new Date().toLocaleString('es-CO') + '\n\n';
mdReport += 'Categorias:\n';
Object.keys(byCategory).forEach(cat => {
  const c = byCategory[cat];
  const icon = c.failed === 0 ? 'OK' : 'FAIL';
  mdReport += icon + ' ' + cat + ': ' + c.passed + '/' + c.total + '\n';
});
if (failed.length > 0) {
  mdReport += '\nFallos Detectados:\n';
  failed.forEach(f => {
    mdReport += '- [' + f.priority + '] ' + f.testName + '\n';
    mdReport += '  Exp: ' + f.ruleDescription + '\n';
    mdReport += '  Got: ' + f.output + '\n';
  });
}
console.log('\n' + mdReport);
return [{
  json: {
    meta: { timestamp: new Date().toISOString(), totalTests: total, success: failed.length === 0, workflow: 'GymBotWorkoutCompletion' },
    markdownReport: mdReport,
    stats: { passed: passed.length, failed: failed.length, rate: parseFloat(passRate), byCategory },
    failures: failed.map(r => ({ testId: r.testId, name: r.testName, category: r.category, reason: r.ruleDescription, output: r.output }))
  }
}];
